  'stanley.door.before': 'Stanley is the one place to ask, and he loves a question. Before you book, he answers from the cruise information in this app, and tells you where each answer came from.',
  'stanley.door.ship': 'Stanley is the one place to ask, and he loves a question. For the ship, he answers from ship information we have written, and says when he does not know.',
